(function () {
  'use strict';
  window.QUESTION_BANK = Object.assign(window.QUESTION_BANK || {}, {"grammar-subject-predicate":{"title":"Subject and Predicate","topic":"Grammar & Usage","questions":[{"id":"grammar-subject-predicate-q0001","version":4,"contentHash":"sha256:146a0ab80144ba6fdfb1b4b66cb89ed437506e129d5b363b5bb81bdabf427981","question":"What is the simple subject: 'The tall boy kicked the ball.'","choices":["The tall boy","boy","kicked the ball","tall"],"correct":1,"explanation":{"correct":"Answer: boy. The simple subject is the specific noun that performs the action in the sentence without any of the extra descriptive words like 'the' or 'tall'.","incorrect":[{"choice":"The tall boy","category":"complete subject","reason":"This is the complete subject, which includes the noun and its adjectives. The simple subject is just the main noun itself."},"",{"choice":"kicked the ball","category":"predicate error","reason":"This is the predicate, which tells us what the subject did. The simple subject must be the person or thing doing the action."},{"choice":"tall","category":"adjective confusion","reason":"This word is an adjective that describes the boy, but it is not the person performing the action in the sentence."}]},"studyAid":{"definition":"The simple subject is the main noun or pronoun that performs the verb in a sentence, excluding all adjectives or articles.","example":"The fast dog ran. (Subject: dog) | A large red apple fell. (Subject: apple)","strategyClue":"Find the action word (verb) first, then ask 'Who or what performed this action?' The one-word answer to that question is your simple subject.","link":"https://www.grammar-monster.com/glossary/subject.htm","linkText":"Grammar Monster - Subjects"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"grammar-subject-predicate","sequence":1,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-subject-predicate-q0002","version":4,"contentHash":"sha256:a6f8fb914400deed1fca1973e470d21f8dffacd91b8a4a091e44aa67a7675e1a","question":"What is the simple predicate: 'The dog runs fast.'","choices":["runs fast","runs","The dog","fast"],"correct":1,"explanation":{"correct":"Answer: runs. The simple predicate is always the main verb of the sentence. In this case, 'runs' is the action the dog is doing.","incorrect":[{"choice":"runs fast","category":"complete predicate","reason":"This is the complete predicate, which includes the verb and the adverb describing it. The simple predicate is just the main verb alone."},"",{"choice":"The dog","category":"simple subject","reason":"This phrase is the simple subject, which identifies who or what the sentence is about, not the action they are performing."},{"choice":"fast","category":"adverb identification","reason":"This word is an adverb describing how the dog runs, not the action verb itself."}]},"studyAid":{"definition":"The simple predicate is the main verb of the sentence, which tells what the subject is doing or being.","example":"The cat sleeps. (Simple predicate: sleeps); The boy jumps high. (Simple predicate: jumps)","strategyClue":"Ask yourself, 'What is the action in this sentence?' The word that answers this question is your simple predicate.","link":"https://www.grammar-monster.com/glossary/subject.htm","linkText":"Grammar Monster - Subjects"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"high","sourceSet":"grammar-subject-predicate","sequence":2,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-subject-predicate-q0003","version":4,"contentHash":"sha256:eaea5c6fbb704f9f7d2fcb8b2c6e4e5567b8fad968eabae6ce0c38d7a84e1dd1","question":"What is the complete subject: 'My little sister sings loudly.'","choices":["sings loudly","My little sister","sister","sings"],"correct":1,"explanation":{"correct":"Answer: My little sister. The complete subject includes the noun being talked about along with all the words that describe it. 'My little' describes who the sister is, so they are part of the complete subject.","incorrect":[{"choice":"sings loudly","category":"predicate error","reason":"This part of the sentence describes what the subject is doing, not who is performing the action. This is called the predicate."},"",{"choice":"sister","category":"simple subject only","reason":"While 'sister' is the main noun (simple subject), it is missing the modifiers 'My' and 'little' that help identify exactly which sister we are talking about."},{"choice":"sings","category":"verb error","reason":"The word 'sings' is the action the subject is performing. It is the verb, not the subject."}]},"studyAid":{"definition":"The complete subject includes the main noun (simple subject) and all the words that describe it, telling us exactly who or what the sentence is about.","example":"The tall man jumped. (Complete subject: 'The tall man'); My best friend arrived. (Complete subject: 'My best friend')","strategyClue":"Find the verb first, then ask 'Who or what is doing this?' and include all the words that belong to that person or thing.","link":"https://www.grammar-monster.com/glossary/subject.htm","linkText":"Grammar Monster - Subjects"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"grammar-subject-predicate","sequence":3,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-subject-predicate-q0004","version":4,"contentHash":"sha256:cf66ec3fcc178f1d37dfab6dbda179b194ed81247a1dcfae47d76efc1e39eded","question":"What is the complete predicate: 'The children played in the park.'","choices":["The children","played in the park","played","children"],"correct":1,"explanation":{"correct":"Answer: played in the park. The complete predicate consists of the verb and all the words that describe the action or state of being of the subject.","incorrect":[{"choice":"The children","category":"subject identification error","reason":"This is the complete subject of the sentence, not the predicate. The predicate tells us what the subject did."},"",{"choice":"played","category":"incomplete predicate","reason":"While 'played' is the simple predicate (the verb), it is not the complete predicate because it leaves out the important information about where the action happened."},{"choice":"children","category":"simple subject error","reason":"This is just the simple subject, which is the main noun of the sentence. It does not contain any part of the verb or the action described."}]},"studyAid":{"definition":"The complete predicate of a sentence is the verb plus all the words that modify or complete the verb's meaning.","example":"The dog (subject) / barked loudly at the mailman (complete predicate). We (subject) / ate pizza for dinner (complete predicate).","strategyClue":"First, find the action word (verb). Then, look at all the words that come after the subject and include the verb, asking yourself, 'What is being said about the subject?'","link":"https://www.grammar-monster.com/glossary/subject.htm","linkText":"Grammar Monster - Subjects"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"high","sourceSet":"grammar-subject-predicate","sequence":4,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-subject-predicate-q0005","version":4,"contentHash":"sha256:9c1ca80697f57c03970b22e8e2c1bfb899323fab5272fef8193e72641cccd2eb","question":"What is the subject: 'There are three apples on the table.'","choices":["There","three apples","on the table","are"],"correct":1,"explanation":{"correct":"Answer: three apples. The subject of a sentence is the person, place, or thing that the sentence is about or performing the action. In this sentence, 'three apples' is the thing that is being described as existing.","incorrect":[{"choice":"There","category":"introductory word error","reason":"'There' is used to introduce the sentence, but it is not the actual subject. It acts as an expletive or placeholder."},"",{"choice":"on the table","category":"prepositional phrase error","reason":"This phrase describes the location of the apples, not the subject itself. It is a prepositional phrase that adds extra detail."},{"choice":"are","category":"verb identification error","reason":"'Are' is the linking verb in this sentence, not the subject. The verb tells us what the subject is doing or being."}]},"studyAid":{"definition":"The subject is the part of the sentence that tells us who or what the sentence is about. It usually comes before the verb in a statement.","example":"The dog barked (Subject: The dog), Six birds flew away (Subject: Six birds)","strategyClue":"Ask yourself, 'What or who exists or is being talked about?' The words answering that question are your subject.","link":"https://www.grammar-monster.com/glossary/subject.htm","linkText":"Grammar Monster - Subjects"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"grammar-subject-predicate","sequence":5,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-subject-predicate-q0006","version":4,"contentHash":"sha256:b7509c15ff2958f498e9e83c61e5ecf0e5da82586790f4f52597931ade5c3106","question":"What is the predicate: 'The sun rises in the east.'","choices":["The sun","rises in the east","rises","in the east"],"correct":1,"explanation":{"correct":"Answer: rises in the east. The predicate includes the verb and all the words that explain what the subject is doing or what is happening to it.","incorrect":[{"choice":"The sun","category":"subject identification","reason":"This is the subject of the sentence, not the predicate. The subject tells us who or what the sentence is about."},"",{"choice":"rises","category":"incomplete predicate","reason":"While 'rises' is the verb, the predicate includes all the words that follow it to complete the thought about the subject."},{"choice":"in the east","category":"prepositional phrase","reason":"This is only a part of the predicate. You must include the verb 'rises' to show the full action of the subject."}]},"studyAid":{"definition":"The predicate is the part of the sentence that tells what the subject does or is. It always contains the verb.","example":"The dog (subject) barked loudly (predicate). Birds (subject) fly south for winter (predicate).","strategyClue":"Find the verb first, then ask yourself, 'What is the rest of the sentence that tells us what the subject is doing?' Include all words from the verb to the end of the phrase.","link":"https://www.grammar-monster.com/glossary/subject.htm","linkText":"Grammar Monster - Subjects"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"high","sourceSet":"grammar-subject-predicate","sequence":6,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-subject-predicate-q0007","version":4,"contentHash":"sha256:b325b20184caac484287cbcf0bbf024bb62eeb9709317327e569adc41596d842","question":"What is the simple subject: 'A group of birds flew overhead.'","choices":["A group of birds","group","flew overhead","birds"],"correct":1,"explanation":{"correct":"Answer: group. The simple subject is the single noun that tells us who or what the sentence is about, without any extra descriptive words.","incorrect":[{"choice":"A group of birds","category":"complete subject error","reason":"This is the complete subject. It includes the simple subject plus all the extra words that describe it, but the simple subject is just the one core noun."},"",{"choice":"flew overhead","category":"predicate identification error","reason":"This is the predicate, which tells us what the subject did. The subject is who or what performs the action, not the action itself."},{"choice":"birds","category":"object of preposition error","reason":"While 'birds' is a noun, it is part of a phrase describing the 'group.' In this sentence, the 'group' is the main word doing the action of flying."}]},"studyAid":{"definition":"The simple subject is the main noun or pronoun that the sentence is about, stripped of all descriptive words and phrases.","example":"The big red ball bounced. (Simple subject: ball) | Two tired puppies slept. (Simple subject: puppies)","strategyClue":"Find the verb first, then ask, 'Who or what performed this action?' Look for the one main noun that answers that question before the prepositional phrase begins.","link":"https://www.grammar-monster.com/glossary/subject.htm","linkText":"Grammar Monster - Subjects"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"grammar-subject-predicate","sequence":7,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-subject-predicate-q0008","version":4,"contentHash":"sha256:9ae716ef4b8d0693d6ee6a935bb791934aa1405fcf3d6200771b57bd31e482e2","question":"What is the simple predicate: 'She has been studying for hours.'","choices":["has been studying","studying","has","for hours"],"correct":0,"explanation":{"correct":"Answer: has been studying. The simple predicate is the main verb or verb phrase that tells what the subject is doing or experiencing. Because 'has been studying' is a verb phrase showing a continuous action, all three words are necessary to complete the predicate.","incorrect":["",{"choice":"studying","category":"incomplete verb phrase","reason":"While 'studying' is the main action, it is missing the helping verbs 'has been' that show the tense of the sentence."},{"choice":"has","category":"helping verb only","reason":"'Has' is only part of the verb phrase. A simple predicate includes the helping verbs along with the main action verb."},{"choice":"for hours","category":"prepositional phrase","reason":"'For hours' is a prepositional phrase that tells how long, not what the subject is actually doing. The predicate must be a verb."}]},"studyAid":{"definition":"The simple predicate is the verb or verb phrase that tells what the subject is, has, or does. It may include one or more helping verbs alongside the main verb.","example":"He runs fast. (Simple predicate: runs). She will be playing soccer. (Simple predicate: will be playing).","strategyClue":"Identify the subject, then ask yourself, 'What is the action happening here?' Look for all the words that work together to show that specific action and time.","link":"https://www.grammar-monster.com/glossary/subject.htm","linkText":"Grammar Monster - Subjects"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"high","sourceSet":"grammar-subject-predicate","sequence":8,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-subject-predicate-q0009","version":4,"contentHash":"sha256:9d16ed2b30e5224ca1cb9b23995e3a69a7a8eccf93d8f3761657b7489760b8f5","question":"What is the subject: 'Here is your book.'","choices":["Here","your book","is","book"],"correct":1,"explanation":{"correct":"Answer: your book. In sentences starting with 'Here is' or 'There is', the subject often comes after the verb. By flipping the sentence to 'Your book is here', it is easy to see that 'your book' is the thing performing the action or being described.","incorrect":[{"choice":"Here","category":"adverb of place","reason":"'Here' tells us where the book is, but it is not the thing that the sentence is about. It is an adverb, not the subject."},"",{"choice":"is","category":"linking verb","reason":"'Is' is the verb of the sentence. The subject is the person or thing that 'is' something, so the verb itself cannot be the subject."},{"choice":"book","category":"incomplete noun phrase","reason":"While 'book' is part of the subject, it leaves out the modifier 'your'. The full subject is the complete noun phrase 'your book'."}]},"studyAid":{"definition":"The subject is the part of the sentence that tells us who or what the sentence is about. In some sentences, the subject appears after the verb.","example":"There is a cat. (Subject: a cat), Here are my keys. (Subject: my keys)","strategyClue":"Try rearranging the sentence into a more standard order. If you can move parts around to make the sentence start with a noun or pronoun, that part is likely your subject.","link":"https://www.grammar-monster.com/glossary/subject.htm","linkText":"Grammar Monster - Subjects"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"grammar-subject-predicate","sequence":9,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-subject-predicate-q0010","version":4,"contentHash":"sha256:17bbdaa4b3dec790303c62d999d94859b650e29925f0afe63ffd271523ae5ffd","question":"What is the complete subject: 'The very old man walked slowly.'","choices":["The very old man","man","walked slowly","old man"],"correct":0,"explanation":{"correct":"Answer: The very old man. The complete subject includes the noun acting in the sentence plus all the words that describe or modify it.","incorrect":["",{"choice":"man","category":"simple subject only","reason":"This is only the simple subject (the noun itself). The complete subject must also include the words 'The', 'very', and 'old' that describe the man."},{"choice":"walked slowly","category":"predicate confusion","reason":"This is the predicate, which tells us what the subject did. The subject is the person or thing performing the action, not the action itself."},{"choice":"old man","category":"incomplete phrase","reason":"This misses the determiner 'The' and the modifier 'very'. A complete subject includes every word that belongs to the subject's noun phrase."}]},"studyAid":{"definition":"The complete subject is the person, place, or thing that the sentence is about, plus all the words that describe it.","example":"The big red ball bounced. (Complete subject: 'The big red ball'). Happy puppies barked. (Complete subject: 'Happy puppies').","strategyClue":"Find the verb first, then ask 'Who or what performed this action?' The complete subject includes that answer and every word attached to it before the verb.","link":"https://www.grammar-monster.com/glossary/subject.htm","linkText":"Grammar Monster - Subjects"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"grammar-subject-predicate","sequence":10,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-subject-predicate-q0011","version":4,"contentHash":"sha256:6f8b8636282b0b019e9129544522df5642a19ffb71b7a67cb4af703da67326c2","question":"What is the predicate: 'My friends and I went to the movies.'","choices":["My friends and I","went to the movies","went","friends and I"],"correct":1,"explanation":{"correct":"Answer: went to the movies. The predicate is the part of the sentence that contains the verb and tells us what the subject is doing or what is happening to them.","incorrect":[{"choice":"My friends and I","category":"subject versus predicate","reason":"This is the subject of the sentence, not the predicate. The subject tells us who the sentence is about."},"",{"choice":"went","category":"incomplete predicate","reason":"While 'went' is the verb, the full predicate includes all the words that explain the action, including where the friends went."},{"choice":"friends and I","category":"missing subject components","reason":"This is just a part of the subject noun phrase. The predicate must include the verb that describes the action being taken."}]},"studyAid":{"definition":"A sentence is made of two parts: a subject, who or what the sentence is about, and a predicate, which tells what the subject is doing or describes the subject.","example":"The dog (subject) ran home (predicate). She (subject) is very smart (predicate).","strategyClue":"Find the verb in the sentence first. Start from that verb and include everything that follows it to capture the entire action.","link":"https://www.grammar-monster.com/glossary/subject.htm","linkText":"Grammar Monster - Subjects"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"high","sourceSet":"grammar-subject-predicate","sequence":11,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-subject-predicate-q0012","version":4,"contentHash":"sha256:09f0ab0f14e208b0bb72a692591c55afd4d7c209fcb58d343844a9d5ccd1f629","question":"What is the simple subject: 'Under the table, the cat slept.'","choices":["Under the table","table","the cat","cat"],"correct":3,"explanation":{"correct":"Answer: cat. The simple subject is the main noun or pronoun that the sentence is about. In this sentence, the cat is the one doing the action of sleeping, not the table.","incorrect":[{"choice":"Under the table","category":"prepositional phrase error","reason":"This is a prepositional phrase that describes *where* the action happened, not *who* performed the action. Subjects are never found inside prepositional phrases."},{"choice":"table","category":"noun in phrase","reason":"The word 'table' is part of a prepositional phrase ('Under the table'). It is a noun, but it is not the subject performing the action in this sentence."},{"choice":"the cat","category":"complete subject error","reason":"The phrase 'the cat' is the complete subject, which includes the article. The *simple* subject is just the main noun, which is 'cat'."},""]},"studyAid":{"definition":"The simple subject is the main noun or pronoun that the sentence is about, without any of its describing words (adjectives or articles).","example":"The big red ball bounced. (Simple subject: ball) / Seven hungry kittens played. (Simple subject: kittens)","strategyClue":"Find the verb that describes the action of the sentence, then ask 'Who or what performed this action?' The answer to that question is your simple subject.","link":"https://www.grammar-monster.com/glossary/subject.htm","linkText":"Grammar Monster - Subjects"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"grammar-subject-predicate","sequence":12,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-subject-predicate-q0013","version":4,"contentHash":"sha256:26ff2b3687d0c1e40c9dd5a21813884b9d5bf5d641ec2f618c6a9f242eaf2348","question":"What is the simple predicate: 'The storm might have damaged the roof.'","choices":["might have damaged","damaged","might","have damaged"],"correct":0,"explanation":{"correct":"Answer: might have damaged. The simple predicate is the complete verb phrase that tells what the subject is doing, including all helping verbs.","incorrect":["",{"choice":"damaged","category":"incomplete verb phrase","reason":"This is only the main verb. A simple predicate must include all of the helping verbs, such as 'might' and 'have', that work with the main verb."},{"choice":"might","category":"missing main verb","reason":"This is only a helping verb. The simple predicate needs the entire verb phrase, including the action word that tells what actually happened to the roof."},{"choice":"have damaged","category":"missing helping verb","reason":"This leaves out the first helping verb, 'might'. The simple predicate includes every word in the entire verb phrase."}]},"studyAid":{"definition":"The simple predicate is the main verb or verb phrase that expresses the action or state of the subject. It includes the main verb and all of its helping verbs.","example":"The dog was barking (was barking); They will be leaving (will be leaving); She ate (ate).","strategyClue":"Identify the subject, then find the words that describe the action. Include all words that act as 'helpers' to the main action word to ensure you have the full verb phrase.","link":"https://www.grammar-monster.com/glossary/subject.htm","linkText":"Grammar Monster - Subjects"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"high","sourceSet":"grammar-subject-predicate","sequence":13,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-subject-predicate-q0014","version":4,"contentHash":"sha256:a480f9fd61c62e413b40c4544c5ec5d3097fc9abc9c1fbf6a9cc839dc045363d","question":"What is the subject: 'Swimming is good exercise.'","choices":["Swimming","is","good exercise","exercise"],"correct":0,"explanation":{"correct":"Answer: Swimming. The subject of a sentence is the person, place, thing, or action that the sentence is about. In this sentence, the action of 'Swimming' is what the sentence describes.","incorrect":["",{"choice":"is","category":"verb versus subject","reason":"'Is' is the linking verb in this sentence, not the subject. The subject is the 'who' or 'what' performing the action or being described."},{"choice":"good exercise","category":"predicate phrase error","reason":"'Good exercise' describes the subject, but it is not the subject itself. This part of the sentence tells us more about the subject."},{"choice":"exercise","category":"predicate noun error","reason":"'Exercise' appears at the end of the sentence as the word being defined. The sentence is about the act of swimming, not just the word exercise."}]},"studyAid":{"definition":"The subject is the part of the sentence that names the person, thing, or action the sentence is about. You can usually find the subject by asking 'Who or what is this sentence about?'","example":"Dogs run fast. (Subject: Dogs) / Running is fun. (Subject: Running)","strategyClue":"Locate the main verb in the sentence first. Ask yourself who or what is performing that verb or being described by that verb to find the subject.","link":"https://www.grammar-monster.com/glossary/subject.htm","linkText":"Grammar Monster - Subjects"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"grammar-subject-predicate","sequence":14,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-subject-predicate-q0015","version":4,"contentHash":"sha256:cab3bdacefc5b4fb92ce73192930bf3c6bc12864e5f94a7969b131993a0fc384","question":"What is the complete predicate: 'The big, brown bear caught a fish in the stream.'","choices":["The big, brown bear","caught a fish in the stream","caught","a fish in the stream"],"correct":1,"explanation":{"correct":"Answer: caught a fish in the stream. The complete predicate includes the verb and all the words that describe the action or what is happening in the sentence.","incorrect":[{"choice":"The big, brown bear","category":"complete subject","reason":"This part identifies who or what the sentence is about, making it the complete subject, not the predicate."},"",{"choice":"caught","category":"simple predicate","reason":"This is just the verb, known as the simple predicate. The complete predicate includes the verb and everything that follows it."},{"choice":"a fish in the stream","category":"predicate complement","reason":"This part is only the object and phrase following the verb. A complete predicate must include the verb 'caught' itself."}]},"studyAid":{"definition":"A complete predicate contains the verb and all the words that explain what the subject is doing or what is happening to the subject.","example":"The dog (subject) | barked loudly at the mailman (predicate). She (subject) | read a long book (predicate).","strategyClue":"Find the verb first, then include every word that follows it to describe the action. Do not include the person or thing performing the action.","link":"https://www.grammar-monster.com/glossary/subject.htm","linkText":"Grammar Monster - Subjects"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"medium","6":"medium"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-edit","languageDemand":"sentence-context","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":75,"reviewPriority":"high","sourceSet":"grammar-subject-predicate","sequence":15,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-subject-predicate-q0016","version":4,"contentHash":"sha256:c5cf1eb5bab901e24a87c328a403ea273f59050699ff12e66d72ab74f5c3a72a","question":"What is the simple subject: 'Neither of the answers is correct.'","choices":["Neither of the answers","Neither","answers","correct"],"correct":1,"explanation":{"correct":"Answer: Neither. The simple subject is the main noun or pronoun that performs the action or is being described. In this sentence, 'Neither' is the singular pronoun acting as the subject, while 'of the answers' is a prepositional phrase that provides extra information.","incorrect":[{"choice":"Neither of the answers","category":"complete vs simple subject","reason":"This is the complete subject, which includes the subject and all its modifiers. The simple subject is just the single word that forms the core of the subject."},"",{"choice":"answers","category":"object of preposition","reason":"The word 'answers' is part of a prepositional phrase starting with 'of'. The simple subject is never found inside a prepositional phrase."},{"choice":"correct","category":"adjective misuse","reason":"'Correct' is an adjective that describes the subject. It tells us something about the subject, but it is not the subject itself."}]},"studyAid":{"definition":"The simple subject is the main noun or pronoun that the sentence is about, without any of its describing words or phrases.","example":"The tall man walks. (Simple subject: man); One of the kittens is hungry. (Simple subject: One)","strategyClue":"Cross out any prepositional phrases that start with words like 'of', 'in', 'on', or 'with'. The word left standing alone before the verb is your simple subject.","link":"https://www.grammar-monster.com/glossary/subject.htm","linkText":"Grammar Monster - Subjects"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-subject-predicate","sequence":16,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-subject-predicate-q0017","version":4,"contentHash":"sha256:e835b3648dbaf16aa7e54410a2b6c95b9ac890391ca534e1eeb5bfe7997fe305","question":"In 'Maria and Jason threw a surprise party for their mother,' which choice is the complete subject?","choices":["Maria and Jason","threw","threw a surprise party","for their mother"],"correct":0,"studyAid":{"definition":"The complete subject is all the words that tell us who or what the sentence is about, including any modifiers or connecting words.","example":"The tall man jumped. (Complete subject: The tall man); Sarah and her friend played. (Complete subject: Sarah and her friend)","strategyClue":"Find the action verb in the sentence first. Ask yourself 'Who or what performed this action?' and include all words attached to that name or group.","link":"https://www.grammar-monster.com/","linkText":"Grammar Monster - Grammar Help"},"explanation":{"correct":"Answer: Maria and Jason. The complete subject includes the person or thing performing the action and any words that modify or connect them, such as 'and'.","incorrect":["",{"choice":"threw","category":"predicate verb","reason":"The word 'threw' is the action of the sentence, known as the predicate. The subject is who or what performs that action."},{"choice":"threw a surprise party","category":"predicate phrase","reason":"This phrase contains the action and the object being acted upon. The complete subject must come before the verb 'threw'."},{"choice":"for their mother","category":"prepositional phrase","reason":"This is a prepositional phrase explaining who the party is for. It tells us about the purpose, not who is doing the throwing."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"extended-context","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-subject-predicate","sequence":17,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-subject-predicate-q0018","version":4,"contentHash":"sha256:2e130c9dbef7152784129186264c01e0e5c76da4f866546c245d445cce4be925","question":"In 'The Great Barrier Reef is 1,250 miles long,' which choice is the complete predicate?","choices":["The Great Barrier Reef","is 1,250 miles long","Great Barrier Reef","1,250 miles"],"correct":1,"studyAid":{"definition":"A sentence is split into two parts: the complete subject (who or what) and the complete predicate (the verb and everything after it).","example":"The dog (subject) / barks loudly (predicate). She (subject) / likes apples (predicate).","strategyClue":"Find the verb first. Once you locate the verb, everything from that word to the end of the sentence is part of the complete predicate.","link":"https://www.grammar-monster.com/","linkText":"Grammar Monster - Grammar Help"},"explanation":{"correct":"Answer: is 1,250 miles long. The complete predicate includes the verb and all the words that describe the action or state of being of the subject.","incorrect":[{"choice":"The Great Barrier Reef","category":"subject identification error","reason":"This is the complete subject, not the predicate. It names who or what the sentence is about, rather than telling us something about it."},"",{"choice":"Great Barrier Reef","category":"incomplete subject","reason":"This is just part of the noun phrase used as the subject. It does not include the verb 'is' or any of the descriptive information."},{"choice":"1,250 miles","category":"incomplete predicate","reason":"While this tells us about the length, it leaves out the verb 'is'. A predicate must include the verb for the sentence to be complete."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"medium","6":"medium"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-edit","languageDemand":"sentence-context","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":75,"reviewPriority":"high","sourceSet":"grammar-subject-predicate","sequence":18,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-subject-predicate-q0019","version":4,"contentHash":"sha256:c8fdabec736abf9774aab4270c6cf8e7f68975310d876bbc10586733a44f117c","question":"In 'Josh and his dog Ziggy explore the woods together,' which choice is the simple predicate?","choices":["Josh","dog","explore","the woods together"],"correct":2,"studyAid":{"definition":"The simple predicate is the main verb or action word that tells what the subject of the sentence is doing.","example":"The bird sings. (sings is the predicate) | She runs fast. (runs is the predicate)","strategyClue":"Find the subject by asking 'Who or what is this sentence about?' Then, ask yourself 'What is that person or thing doing?' The word that answers the second question is your simple predicate.","link":"https://www.grammar-monster.com/","linkText":"Grammar Monster - Grammar Help"},"explanation":{"correct":"Answer: explore. The simple predicate is the main verb or action word in the sentence. 'Explore' is the action that Josh and his dog are performing, making it the simple predicate.","incorrect":[{"choice":"Josh","category":"subject noun error","reason":"Josh is a person who performs the action, which makes him the simple subject, not the predicate. Look for the word that tells you what Josh is doing."},{"choice":"dog","category":"common noun error","reason":"The word dog is a noun that helps form the subject of the sentence. It does not describe an action, so it cannot be the predicate."},"",{"choice":"the woods together","category":"complete predicate error","reason":"This phrase contains the object and additional information. The 'simple' predicate is just the single word that represents the main action."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"medium","6":"medium"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-edit","languageDemand":"sentence-context","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":75,"reviewPriority":"high","sourceSet":"grammar-subject-predicate","sequence":19,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-subject-predicate-q0020","version":4,"contentHash":"sha256:f70de3b04cf9b8cd238631367fa1019346aa78070ed7e90a6b799b2f346018c7","question":"In 'Jason and Tina bought a new house,' which choice is the complete predicate?","choices":["Jason and Tina","bought","bought a new house","a new house"],"correct":2,"studyAid":{"definition":"The complete predicate is the part of the sentence that tells us what the subject does or is. It begins with the verb and includes every word that follows it.","example":"The cat (subject) / slept on the rug (complete predicate). We (subject) / ate pizza for dinner (complete predicate).","strategyClue":"First, find the subject performing the action. Then, draw a line through every word that remains in the sentence; that entire group of words is the complete predicate.","link":"https://www.grammar-monster.com/","linkText":"Grammar Monster - Grammar Help"},"explanation":{"correct":"Answer: bought a new house. The complete predicate includes the main verb and all the words that explain what the subject is doing or what is happening to the subject.","incorrect":[{"choice":"Jason and Tina","category":"subject identified","reason":"These are the people performing the action, which makes this the complete subject, not the predicate."},{"choice":"bought","category":"simple predicate only","reason":"This is only the verb, known as the simple predicate. The complete predicate must include the entire phrase describing the action."},"",{"choice":"a new house","category":"direct object only","reason":"This is the object of the verb. It is only one part of the predicate, missing the action verb itself."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"medium","6":"medium"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-edit","languageDemand":"sentence-context","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":75,"reviewPriority":"high","sourceSet":"grammar-subject-predicate","sequence":20,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-subject-predicate-q0021","version":4,"contentHash":"sha256:56c662bbb32eb84adacf6224b27117d051afb9b961ba2a03d540f8e30ff73149","question":"In 'Tammy Hill has ballet on Mondays and Wednesdays,' which choice is the simple subject?","choices":["Tammy Hill","Tammy","has","ballet"],"correct":1,"studyAid":{"definition":"The simple subject is the one main noun or pronoun that the sentence is about, without any extra descriptive words.","example":"The small puppy played. (Simple subject: puppy). My best friend left. (Simple subject: friend).","strategyClue":"Find the verb in the sentence first by asking 'What is happening?' Then, ask 'Who or what is doing that action?' The single word that answers that question is your simple subject.","link":"https://www.grammar-monster.com/","linkText":"Grammar Monster - Grammar Help"},"explanation":{"correct":"Answer: Tammy. The simple subject is the single noun that performs the action or is being described. Even though her full name is Tammy Hill, the base noun performing the action is just 'Tammy'.","incorrect":[{"choice":"Tammy Hill","category":"complete vs simple subject","reason":"This is the complete subject, which includes all the words identifying the person. The simple subject is strictly the main noun itself, without the modifier or surname attached."},"",{"choice":"has","category":"verb versus subject","reason":"This word is the action or verb of the sentence, not the subject. The subject is the person or thing doing the action, while 'has' tells us what the subject possesses or experiences."},{"choice":"ballet","category":"object of the sentence","reason":"In this sentence, 'ballet' is the object being studied or performed. It is not the person performing the action, so it cannot be the subject."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-subject-predicate","sequence":21,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-subject-predicate-q0022","version":4,"contentHash":"sha256:fb45dc41fc23fe2411eb1e80d4d80192ea6d66e37c0cafb1379de5d8292c6f0f","question":"In 'I love to listen to the radio in the car,' which choice is the complete predicate?","choices":["I","love","love to listen to the radio in the car","the radio"],"correct":2,"studyAid":{"definition":"A complete predicate is the part of a sentence that tells what the subject is or does; it includes the verb and all the words that follow it.","example":"The dog (subject) / barked loudly at the mailman (complete predicate). She (subject) / likes to read books (complete predicate).","strategyClue":"Find the subject first, then identify the verb. Everything remaining in the sentence after the subject is part of the complete predicate.","link":"https://www.grammar-monster.com/","linkText":"Grammar Monster - Grammar Help"},"explanation":{"correct":"Answer: love to listen to the radio in the car. The complete predicate includes the verb and all the words that describe the action or state of the subject, excluding the subject itself.","incorrect":[{"choice":"I","category":"subject identification","reason":"'I' is the subject of the sentence, not the predicate. The subject is the person or thing doing the action."},{"choice":"love","category":"simple predicate only","reason":"'love' is just the simple predicate (the verb). The complete predicate must include all the words that explain what the subject loves doing."},"",{"choice":"the radio","category":"incomplete predicate","reason":"'the radio' is only part of the direct object. You must include the verb 'love' and the entire phrase that tells us about the subject's action."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"medium","6":"medium"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-edit","languageDemand":"sentence-context","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":75,"reviewPriority":"high","sourceSet":"grammar-subject-predicate","sequence":22,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-subject-predicate-q0023","version":4,"contentHash":"sha256:e34b859b2665064ce620a0cdf3409c1bbb31d3e3a2a030adfeae2a803504d992","question":"In 'The hammer is broken,' which choice is the complete subject?","choices":["The hammer","hammer","is broken","broken"],"correct":0,"studyAid":{"definition":"The complete subject includes the main noun (the simple subject) plus all the words that describe or point to it.","example":"The big dog barked. (Complete subject: The big dog). My red bike is fast. (Complete subject: My red bike).","strategyClue":"Find the verb first to divide the sentence in two. Look at everything to the left of the verb; that entire group of words is your complete subject.","link":"https://www.grammar-monster.com/","linkText":"Grammar Monster - Grammar Help"},"explanation":{"correct":"Answer: The hammer. The complete subject includes the main noun and all of its modifiers, which tell us exactly who or what the sentence is about.","incorrect":["",{"choice":"hammer","category":"simple subject only","reason":"This is only the simple subject. The complete subject includes the article 'The' along with the noun."},{"choice":"is broken","category":"predicate error","reason":"This part of the sentence is the predicate, which describes what the subject is doing or what is happening to it, not the subject itself."},{"choice":"broken","category":"adjective error","reason":"This word is an adjective describing the state of the hammer, not the subject itself. Subjects are usually nouns or pronouns."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"grammar-subject-predicate","sequence":23,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-subject-predicate-q0024","version":4,"contentHash":"sha256:11e172c0290a3c4bbc662b5c6fc4194ef11cac1b4a147951151e16df8bb76308","question":"In 'I visited my grandfather,' which choice is the simple predicate?","choices":["I","visited","my grandfather","visited my grandfather"],"correct":1,"studyAid":{"definition":"The simple predicate is the main verb of the sentence. It tells exactly what the subject is doing or what state of being the subject is in.","example":"The dog barked (simple predicate: barked); She sang a song (simple predicate: sang).","strategyClue":"Find the noun that is performing the action, then ask yourself: 'What word describes exactly what that person or thing is doing?' Only pick that one action word.","link":"https://www.grammar-monster.com/","linkText":"Grammar Monster - Grammar Help"},"explanation":{"correct":"Answer: visited. The simple predicate is the main action word or verb in the sentence. In this sentence, the action performed is 'visited'.","incorrect":[{"choice":"I","category":"subject identification","reason":"'I' is the subject of the sentence, not the action. The subject tells us who or what is performing the action."},"",{"choice":"my grandfather","category":"direct object","reason":"'my grandfather' is the object being visited, not the action itself. The predicate must be the verb."},{"choice":"visited my grandfather","category":"complete predicate","reason":"This is the complete predicate. A simple predicate contains only the main verb, while the complete predicate includes the verb and all the words that describe the action."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"high","sourceSet":"grammar-subject-predicate","sequence":24,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-subject-predicate-q0025","version":4,"contentHash":"sha256:ca55f7292c8f2e294fc88d25e1b4b491f8745569446b722aeb40b8e52c5bef17","question":"Identify the complete predicate of the sentence below. The art lesson covered all the primary colors.","choices":["The art lesson","lesson covered","covered all","covered all the primary colors"],"correct":3,"explanation":{"correct":"Answer: covered all the primary colors. The complete predicate includes the main verb and all the words that explain what the subject did or what happened to it.","incorrect":[{"choice":"The art lesson","category":"subject identification","reason":"This is the complete subject of the sentence, not the predicate. The subject identifies who or what the sentence is about."},{"choice":"lesson covered","category":"incomplete predicate","reason":"This choice misses the rest of the information that tells us exactly what the lesson covered. A complete predicate must include all words following the subject."},{"choice":"covered all","category":"fragmented predicate","reason":"This choice stops too early. To find the complete predicate, include the verb and all the remaining words that finish the thought."},""]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"hard","6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"use the source question clue and compare each answer choice to the rule","estimatedTimeSeconds":60,"reviewPriority":"normal","sourceSet":"grammar-subject-predicate","sequence":25,"sourceFile":"Advanced-6_grammer and usage.pdf","sourceQuestionNumber":1,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]},"studyAid":{"definition":"The complete predicate is the part of the sentence that contains the verb and tells what the subject is doing or what is happening to the subject.","example":"The dog (subject) ran quickly home (predicate). My sister (subject) loves to eat pizza (predicate).","strategyClue":"Find the subject first, then look for the verb. Everything from the verb to the end of the sentence makes up the complete predicate.","link":"","linkText":""}},{"id":"grammar-subject-predicate-q0026","version":4,"contentHash":"sha256:e3c112e6c3a3931418697deaa5a8e445d7e5ccc0f93af3b2154a2a73f5093aeb","question":"Which shows the subject and predicate divided correctly?","choices":["The/whole family waved good-bye to me.","The whole family waved/good-bye to me.","The whole/family waved good-bye to me.","The whole family/ waved good-bye to me."],"correct":3,"explanation":{"correct":"Answer: The whole family/ waved good-bye to me. A sentence is divided between the complete subject (who or what the sentence is about) and the complete predicate (the action or state of the subject). 'The whole family' is the complete subject, and 'waved good-bye to me' is the complete predicate.","incorrect":[{"choice":"The/whole family waved good-bye to me.","category":"Incomplete subject","reason":"This division separates the article 'The' from the noun 'family'. The complete subject includes all the words that describe the person or thing, so keep 'The' with the rest of the subject."},{"choice":"The whole family waved/good-bye to me.","category":"Incorrect predicate split","reason":"This splits the verb phrase 'waved' from its object 'good-bye'. The predicate must include the entire action and everything that follows it."},{"choice":"The whole/family waved good-bye to me.","category":"Subject noun separation","reason":"This splits the subject incorrectly by separating the word 'whole' from the noun 'family'. The complete subject must stay together as one unit before the verb."},""]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"easy","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"use the source question clue and compare each answer choice to the rule","estimatedTimeSeconds":40,"reviewPriority":"normal","sourceSet":"grammar-subject-predicate","sequence":26,"sourceFile":"Basic-6_grammer and usage.pdf","sourceQuestionNumber":3,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]},"studyAid":{"definition":"A sentence is divided into two parts: the complete subject (who/what) and the complete predicate (the action). The break should always occur right before the main verb.","example":"The tall tree / swayed in the wind. My best friend / loves to play soccer.","strategyClue":"Locate the main action verb in the sentence. Place a divider immediately before that verb to separate the subject from the predicate.","link":"","linkText":""}},{"id":"grammar-subject-predicate-q0027","version":4,"contentHash":"sha256:fdb464823ec1b9b149f75eb66a01fdae036f5148f146742632ecf05a4e8352d9","question":"Which choice identifies the complete subject of the sentence: The bunny feels cuddly?","choices":["bunny","The bunny","feels cuddly","cuddly"],"correct":1,"explanation":{"correct":"Answer: The bunny. The complete subject includes the main noun and all of its modifiers. In this sentence, 'The bunny' is the person, place, or thing that the sentence is about.","incorrect":[{"choice":"bunny","category":"simple subject error","reason":"This is only the simple subject. You missed the word 'The,' which is a modifier that belongs to the complete subject."},"",{"choice":"feels cuddly","category":"predicate error","reason":"This part of the sentence is the predicate, which describes what the subject is doing or how it feels. The complete subject is who or what the sentence is about."},{"choice":"cuddly","category":"adjective identification error","reason":"The word 'cuddly' is an adjective describing the bunny. It is part of the predicate, not the subject."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"medium","5":"medium","6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"use the source question clue and compare each answer choice to the rule","estimatedTimeSeconds":50,"reviewPriority":"normal","sourceSet":"grammar-subject-predicate","sequence":27,"sourceFile":"Proficient-4_grammer and usage.pdf","sourceQuestionNumber":2,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]},"studyAid":{"definition":"The complete subject includes the main noun of the sentence plus all the words that describe or point to that noun.","example":"The big dog barked. (Complete subject: The big dog). My red bike is fast. (Complete subject: My red bike).","strategyClue":"Find the verb first, then draw a line before it. Everything to the left of your line is the complete subject.","link":"","linkText":""}},{"id":"grammar-subject-predicate-q0028","version":4,"contentHash":"sha256:67ce5c244566d4ac355f4e2084029c98f4c28e37b0088fbc7244b3b3c5735920","question":"The two main parts of a sentence are:","choices":["su bject and predicate","predicate and direct object","subject and noun","object and verb phrase"],"correct":0,"explanation":{"correct":"Answer: subject and predicate. Every complete sentence must have a subject, which tells who or what the sentence is about, and a predicate, which tells what the subject is doing or what is true about it.","incorrect":["",{"choice":"predicate and direct object","category":"missing sentence part","reason":"While a direct object can be part of a predicate, a sentence must have a subject to be complete. This choice leaves out the person or thing performing the action."},{"choice":"subject and noun","category":"confused part of speech","reason":"A noun is a type of word, not a structural part of a sentence. A subject is often a noun, but the sentence also requires a predicate to function."},{"choice":"object and verb phrase","category":"incomplete sentence structure","reason":"A verb phrase is part of the predicate, but an object is optional. A sentence requires a subject to function, which is missing from this choice."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"medium","5":"medium","6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"use the source question clue and compare each answer choice to the rule","estimatedTimeSeconds":50,"reviewPriority":"normal","sourceSet":"grammar-subject-predicate","sequence":28,"sourceFile":"Proficient-6_grammer and usage.pdf","sourceQuestionNumber":8,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]},"studyAid":{"definition":"A complete sentence must contain two main parts: the subject (who or what) and the predicate (what happened).","example":"Dogs (subject) bark (predicate). The boy (subject) ran quickly to the store (predicate).","strategyClue":"Ask yourself: 'Who or what is this about?' to find the subject, and 'What is happening?' to find the predicate. A sentence is incomplete if it lacks either one.","link":"","linkText":""}},{"id":"grammar-subject-predicate-q0029","version":4,"contentHash":"sha256:2d04345dc6d8565696c676f8d3bbdc97b452f4ef5c8cd870c61246b64e8f7f62","question":"Which sentence has the subject and predicate separated correctly?","choices":["The three boys chased the sheep into the barn / for the night.","The three boys chased / the sheep into the barn for the night.","The three boys / chased the sheep into the barn for the night.","The three boys chased the sheep / into the barn for the night."],"correct":2,"explanation":{"correct":"Answer: The three boys / chased the sheep into the barn for the night. A sentence is split between the complete subject, which tells who or what the sentence is about, and the complete predicate, which contains the verb and tells what the subject is doing.","incorrect":[{"choice":"The three boys chased the sheep into the barn / for the night.","category":"predicate split error","reason":"This break cuts right through the middle of the predicate's prepositional phrase, leaving the main action verb attached to the subject, which is incorrect."},{"choice":"The three boys chased / the sheep into the barn for the night.","category":"verb/object split error","reason":"This split incorrectly separates the verb 'chased' from its direct object 'the sheep', disrupting the main action of the sentence."},"",{"choice":"The three boys chased the sheep / into the barn for the night.","category":"phrase split error","reason":"This break separates the action from the location, failing to capture the full subject and the full predicate correctly."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"hard","6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"grammar-subject-predicate","sequence":29,"sourceFile":"Advanced-2_language Usage.pdf","sourceQuestionNumber":10,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.usage","grammar.writing"],"standardIds":["L.3-6.1","W.3-6.5"]},"studyAid":{"definition":"Every complete sentence has two main parts: a complete subject (the 'who' or 'what') and a complete predicate (the action or state of being).","example":"The small dog / barked loudly. | My best friend / loves to paint pictures.","strategyClue":"Find the main action verb first, then look back to the beginning of the sentence to see which words describe the person or thing performing that action.","link":"","linkText":""}},{"id":"grammar-subject-predicate-q0030","version":4,"contentHash":"sha256:b1b086ce72f82d9be9c52d927873bd77a6f99f4ecfb2675c31c813f4a2a64654","question":"What is the complete predicate in this sentence? Someone stole my lunchbox.","choices":["stole","stole my","stole my lunchbox","someone stole my lunchbox"],"correct":2,"explanation":{"correct":"Answer: stole my lunchbox. The complete predicate includes the verb and all the words that tell us what the subject is doing or what is happening to the subject.","incorrect":[{"choice":"stole","category":"simple predicate only","reason":"This is only the simple predicate, or the verb itself. A complete predicate includes the verb plus the objects or descriptions that follow it."},{"choice":"stole my","category":"incomplete phrase","reason":"This choice cuts off the phrase too early. The complete predicate must contain all words that describe the action taken on the subject's lunchbox."},"",{"choice":"someone stole my lunchbox","category":"entire sentence","reason":"This is the entire sentence, including the subject 'someone'. The predicate does not include the subject."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"hard","6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"grammar-subject-predicate","sequence":30,"sourceFile":"Advanced-2_language Usage.pdf","sourceQuestionNumber":46,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.usage","grammar.writing"],"standardIds":["L.3-6.1","W.3-6.5"]},"studyAid":{"definition":"The complete predicate is the part of the sentence that tells what the subject does or is, consisting of the verb and all the words that modify it.","example":"The dog (subject) ran fast (complete predicate). / She (subject) ate a giant apple (complete predicate).","strategyClue":"First, find the subject of the sentence. Once you identify who or what the sentence is about, look at every remaining word; those words together form the complete predicate.","link":"","linkText":""}},{"id":"grammar-subject-predicate-q0031","version":6,"contentHash":"sha256:bb9974ea8adf43057cf58d97cba9590ee427374941ee1faf67f35dd4e016100b","question":"Identify the correct missing words. Dinosaurs _________________ long ago.","choices":["did live","in the zoo","at the museum","bigger than a chicken"],"correct":0,"explanation":{"correct":"Answer: did live. The phrase 'did live' correctly shows an action that happened in the past, matching the time indicator 'long ago'.","incorrect":["",{"choice":"in the zoo","category":"wrong prepositional phrase","reason":"While this tells us where they might be, it does not describe an action. A sentence needs a verb to show what the subject was doing."},{"choice":"at the museum","category":"incorrect sentence completion","reason":"This phrase describes a location rather than an action. To complete the sentence, you need a verb that tells us what dinosaurs did in the past."},{"choice":"bigger than a chicken","category":"incorrect comparison","reason":"This describes the size of a dinosaur, but it lacks a verb. The sentence needs an action word to tell us what dinosaurs 'did' long ago."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"easy","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"grammar-subject-predicate","sequence":31,"sourceFile":"Basic-5_Writing strategies_Application_Style.pdf","sourceQuestionNumber":5,"sourceCategory":"writing-strategies-application-style","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.usage","grammar.writing"],"standardIds":["L.3-6.1","W.3-6.5"]},"studyAid":{"definition":"Sentences must contain a verb to describe an action, state of being, or occurrence. Past tense verbs are used to describe actions that are already finished.","example":"Correct: They did jump. Incorrect: They at the park (missing verb). Correct: He did sleep. Incorrect: He big (missing verb).","strategyClue":"Ask yourself: 'Does this phrase tell me what the dinosaurs were doing?' If the words only describe a place or a size, look for the option that includes an action word.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"}},{"id":"grammar-subject-predicate-q0032","version":4,"contentHash":"sha256:05bb33e733536f14c7b3f1890c3fa31223f5c8937c85cee46a61178293020063","question":"Which sentence has the subject and predicate separated correctly?","choices":["Corn grows all over / the Midwest.","Corn grows all / over the Midwest.","Corn / grows all over the Midwest.","Corn grows / all over the Midwest."],"correct":2,"explanation":{"correct":"Answer: Corn / grows all over the Midwest. The subject is 'Corn' (who or what the sentence is about), and the predicate is 'grows all over the Midwest' (what the subject is doing or being). Dividing them here correctly separates the naming part from the action part.","incorrect":[{"choice":"Corn grows all over / the Midwest.","category":"incorrect predicate split","reason":"This puts the slash in the middle of a prepositional phrase. The subject is just 'Corn,' so the split must happen immediately after it."},{"choice":"Corn grows all / over the Midwest.","category":"incorrect verb split","reason":"This choice cuts the verb 'grows' off from the rest of the predicate. The subject and predicate should be divided at the point where the naming of the subject ends."},"",{"choice":"Corn grows / all over the Midwest.","category":"incorrect subject inclusion","reason":"This choice incorrectly includes the verb 'grows' as part of the subject. A subject is typically just the noun or pronoun performing the action."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"medium","5":"medium","6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-subject-predicate","sequence":32,"sourceFile":"Proficient-1_language Usage.pdf","sourceQuestionNumber":10,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.usage","grammar.writing"],"standardIds":["L.3-6.1","W.3-6.5"]},"studyAid":{"definition":"Every complete sentence has two parts: the subject, which is who or what the sentence is about, and the predicate, which tells what the subject does or is.","example":"Cats / sleep all day. (Subject: Cats, Predicate: sleep all day); The big dog / barked loudly. (Subject: The big dog, Predicate: barked loudly).","strategyClue":"Find the main action verb in the sentence first. Ask yourself who or what is performing that action, and place your divider immediately after that word.","link":"","linkText":""}},{"id":"grammar-subject-predicate-q0033","version":4,"contentHash":"sha256:66deec4dcae47449524fe32a2e4e53953c30456649c84e2f0dacce8721237eff","question":"Which sentence has the subject and predicate separated correctly?","choices":["The plastic / bird blew off our porch step.","The plastic bird blew / off our porch step.","The plastic bird blew off / our porch step.","The plastic bird / blew off our porch step."],"correct":3,"explanation":{"correct":"Answer: The plastic bird / blew off our porch step. The complete subject is 'The plastic bird' and the predicate begins with the verb 'blew'. Dividing the sentence here clearly separates the person or thing doing the action from the action itself.","incorrect":[{"choice":"The plastic / bird blew off our porch step.","category":"subject split error","reason":"This splits the subject 'The plastic bird' in half. You should keep all the words that describe the bird together before the break."},{"choice":"The plastic bird blew / off our porch step.","category":"verb phrase split","reason":"This splits the verb 'blew' from the rest of its phrase 'off our porch step'. The predicate should include all the words describing what happened to the subject."},{"choice":"The plastic bird blew off / our porch step.","category":"prepositional phrase split","reason":"This breaks the sentence in the middle of a prepositional phrase. The subject is already fully complete before the word 'blew'."},""]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"medium","5":"medium","6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-subject-predicate","sequence":33,"sourceFile":"Proficient-2_language Usage.pdf","sourceQuestionNumber":10,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.usage","grammar.writing"],"standardIds":["L.3-6.1","W.3-6.5"]},"studyAid":{"definition":"The subject is the 'who' or 'what' the sentence is about, and the predicate is the 'action' or 'state' part. A sentence can be divided into these two main parts.","example":"The hungry cat / ate all the tuna. The dark clouds / gathered in the sky.","strategyClue":"Find the main action word (verb) first. Everything before that word belongs to the subject, and that word plus everything after it belongs to the predicate.","link":"","linkText":""}},{"id":"grammar-subject-predicate-q0054","version":4,"contentHash":"sha256:913352cb259489cc6790edadaa68102a20cef7e23430bdcbf81ad273bcee79bd","question":"Read the sentence. Choose the answer that names the simple subject. Everyone drinks soda at sschool dance. the","choices":["Everyone","drinks","the","dance"],"correct":0,"explanation":{"correct":"Answer: Everyone. The simple subject is the main noun or pronoun that performs the action in the sentence. In this case, 'Everyone' is the pronoun acting as the subject who 'drinks'.","incorrect":["",{"choice":"drinks","category":"verb versus subject","reason":"'Drinks' is the action word, or simple predicate, not the subject. The subject is who or what is performing the action."},{"choice":"the","category":"article error","reason":"'The' is an article used to introduce a noun. It cannot function as the subject of a sentence."},{"choice":"dance","category":"object of preposition","reason":"'Dance' is part of a prepositional phrase telling where the action happens. It is not the person or thing performing the action of drinking."}]},"studyAid":{"definition":"The simple subject is the main noun or pronoun in the sentence that tells you who or what is performing the action.","example":"The tall man jumped. (Subject: man). She sings loudly. (Subject: She).","strategyClue":"Find the verb that shows the action, then ask yourself 'Who or what?' before that verb to identify the subject.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["grammar and usage","language","grade 4"],"feedbackFocus":"use the grammar rule and sentence context to compare each answer choice","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"grammar-subject-predicate","sourceFile":"Basic Quiz 3_Language_Grammar and Usage_ MAP 4th Grade.pdf","sourceQuestionNumber":4,"sourceCategory":"grammar-and-usage","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":54,"skillIds":["grammar.usage"],"standardIds":["L.3-6.1"]}}],"metadata":{"gradesSupported":[3,4,5,6],"difficultiesSupported":["easy","medium","hard"],"selectorPolicy":"grade+difficulty selects exact matches first, then nearby grade-appropriate practice to fill the configured mission length"}}}
  );
})();
